70	// ListMemoShares lists all share links for a memo.
71	// Only the memo's creator or an admin may call this.
72	func (s *APIV1Service) ListMemoShares(ctx context.Context, request *v1pb.ListMemoSharesRequest) (*v1pb.ListMemoSharesResponse, error) {
